    /** Writes the COMMAREA's bytes back into the object the task carries (a LINKed program's is its caller's). */
    private Runnable caBack = () -> { };

    @SuppressWarnings("unchecked")
    private <E> DetCics.Store<E> store(String name) {
        return (DetCics.Store<E>) stores.computeIfAbsent(name, n -> switch (n) {
            case "CCXREF" -> new DetCics.Store<CardXrefRecord>(cardXrefRecordRepository::findAll, e -> e.toRecord(CS), b -> CardXrefRecord.fromRecord(b, CS), cardXrefRecordRepository::save, cardXrefRecordRepository::delete, 0, 16, CS).withFindById(rec -> cardXrefRecordRepository.findById(id_CardXrefRecord(rec)));
            case "CXACAIX" -> new DetCics.Store<CardXrefRecord>(cardXrefRecordRepository::findAll, e -> e.toRecord(CS), b -> CardXrefRecord.fromRecord(b, CS), cardXrefRecordRepository::save, cardXrefRecordRepository::delete, 25, 11, CS);
            case "TRANSACT" -> new DetCics.Store<TranRecord>(tranRecordRepository::findAll, e -> e.toRecord(CS), b -> TranRecord.fromRecord(b, CS), tranRecordRepository::save, tranRecordRepository::delete, 0, 16, CS).withFindById(rec -> tranRecordRepository.findById(id_TranRecord(rec)));
            default -> throw new Hole("CICS file " + n + ": no store in the generated project");
        });
    }

